.trrsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2a23;
    background:
        radial-gradient(circle at 88% 4%, rgba(214, 138, 58, 0.10) 0%, rgba(214, 138, 58, 0) 42%),
        linear-gradient(180deg, #f7f1e4 0%, #efe6d2 100%);
    border-radius: 18px;
}

.trrsim-container * {
    box-sizing: border-box;
}

.trrsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f2a4d 0%, #2c3a63 52%, #5a3a72 100%);
    color: #f6efe0;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #14203f;
    box-shadow: 0 14px 36px rgba(31, 42, 77, 0.35);
}

.trrsim-header h1 {
    margin: 10px 0 12px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: 0.2px;
    color: #fbf6ea;
}

.trrsim-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0b35e;
    background: rgba(240, 179, 94, 0.12);
    border: 1px solid rgba(240, 179, 94, 0.34);
    padding: 5px 14px;
    border-radius: 999px;
}

.trrsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #d8d0c0;
}

.trrsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6a5f4d;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.trrsim-period-counter #currentDay,
.trrsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f2a4d;
}

.trrsim-round-name {
    background: rgba(31, 42, 77, 0.10);
    color: #1f2a4d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.trrsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8451f;
    background: rgba(168, 69, 31, 0.10);
    border: 1px solid rgba(168, 69, 31, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.trrsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.trrsim-status-card {
    background: linear-gradient(160deg, #fffaf0 0%, #f4ecda 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d4ba;
    box-shadow: 0 6px 16px rgba(120, 96, 52, 0.14);
    border-top: 4px solid #b8a988;
}

.trrsim-card-access { border-top-color: #1f7a52; }
.trrsim-card-legal { border-top-color: #2c3a63; }
.trrsim-card-rep { border-top-color: #a8451f; }
.trrsim-card-jobs { border-top-color: #c9892b; }

.trrsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a5c;
}

.trrsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2e2a23;
    font-variant-numeric: tabular-nums;
}

.trrsim-card-access .trrsim-value { color: #1f7a52; }
.trrsim-card-legal .trrsim-value { color: #2c3a63; }
.trrsim-card-rep .trrsim-value { color: #a8451f; }
.trrsim-card-jobs .trrsim-value { color: #b5781f; }

.trrsim-sublabel {
    font-size: 0.76rem;
    color: #8a7a5c;
    line-height: 1.35;
}

/* Story colours: access high = good, low = danger */
.trrsim-access-low { border-top-color: #c0392b; }
.trrsim-access-low .trrsim-value { color: #c0392b; }
.trrsim-access-high { border-top-color: #1f7a52; }
.trrsim-access-high .trrsim-value { color: #1f7a52; }

/* Legal exposure & reputational risk: high = danger */
.trrsim-risk-high { border-top-color: #c0392b; }
.trrsim-risk-high .trrsim-value { color: #c0392b; }
.trrsim-risk-low .trrsim-value { color: #1f7a52; }

.trrsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f2a4d;
    border: 1px solid #14203f;
    color: #e8e0cd;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.trrsim-budget-bar #budgetDisplay {
    font-size: 1.08rem;
    letter-spacing: 0.3px;
    color: #f0b35e;
}

.trrsim-budget-bar.trrsim-budget-over #budgetDisplay {
    color: #ff8a6b;
}

.trrsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #fffaf0 0%, #f3eada 100%);
    border-left: 5px solid #c9892b;
    border-radius: 12px;
    padding: 17px 19px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(120, 96, 52, 0.12);
}

.trrsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.trrsim-briefing-title {
    font-family: Georgia, 'Times New Roman', serif;
    font-weight: 800;
    font-size: 1.12rem;
    color: #1f2a4d;
    margin-bottom: 6px;
}

.trrsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #463f33;
}

.trrsim-briefing-text strong { color: #1f7a52; }
.trrsim-briefing-text em { color: #a8451f; font-style: italic; }

.trrsim-controls {
    background: linear-gradient(160deg, #fffdf7 0%, #f6efdf 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d4ba;
    box-shadow: 0 6px 16px rgba(120, 96, 52, 0.12);
}

.trrsim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.14rem;
    font-weight: 800;
    color: #1f2a4d;
    border-bottom: 2px solid #e0d4ba;
    padding-bottom: 8px;
}

.trrsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a3428;
    margin: 16px 0 6px;
}

.trrsim-container select,
.trrsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbb992;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf7;
    color: #2e2a23;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.trrsim-container select:focus,
.trrsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9892b;
    box-shadow: 0 0 0 3px rgba(201, 137, 43, 0.20);
}

.trrsim-container select option {
    background-color: #fffdf7;
    color: #2e2a23;
}

.trrsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9892b;
}

.trrsim-range-readout,
.trrsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6a5f4d;
    margin-top: 4px;
}

.trrsim-range-readout span:last-child,
.trrsim-alloc-readout span:nth-child(2) {
    color: #1f7a52;
    font-weight: 800;
}

.trrsim-hint {
    font-size: 0.8rem;
    color: #8a7a5c;
    margin-top: 6px;
    line-height: 1.45;
}

.trrsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.trrsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fbf5e8;
    border: 1px solid #e0d4ba;
    border-radius: 9px;
    padding: 9px 13px;
}

.trrsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #463f33;
}

.trrsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.trrsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.trrsim-container .btn-primary {
    background: linear-gradient(135deg, #1f2a4d 0%, #c9892b 130%);
    border: none;
    color: #fbf6ea;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(31, 42, 77, 0.32);
}

.trrsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.trrsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbb992;
    color: #6a5f4d;
    background: transparent;
}

.trrsim-coach {
    background: linear-gradient(160deg, #1f2a4d 0%, #2a2340 100%);
    color: #e4dccb;
    border: 1px solid #14203f;
    border-radius: 14px;
    padding: 17px 21px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 42, 77, 0.30);
}

.trrsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b35e;
    margin-bottom: 8px;
}

.trrsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.trrsim-coach-body strong { color: #7ed3a6; }
.trrsim-coach-body em { color: #f0b35e; font-style: italic; }

.trrsim-history,
.trrsim-chart {
    background: linear-gradient(160deg, #fffdf7 0%, #f6efdf 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d4ba;
    box-shadow: 0 6px 16px rgba(120, 96, 52, 0.12);
}

.trrsim-history h3,
.trrsim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.1rem;
    font-weight: 800;
    color: #1f2a4d;
}

.trrsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #463f33;
}

.trrsim-container table#usfHistoryTable th {
    background: #1f2a4d;
    color: #f0b35e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #14203f;
}

.trrsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6dcc4;
    color: #463f33;
}

.trrsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf3e4;
}

.trrsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .trrsim-container {
        padding: 14px;
    }
    .trrsim-header h1 {
        font-size: 1.7rem;
    }
    .trrsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .trrsim-value {
        font-size: 2.1rem;
    }
    .trrsim-clock {
        margin-left: 0;
    }
    .trrsim-period-counter {
        font-size: 0.88rem;
    }
    .trrsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .trrsim-alloc-row {
        flex-wrap: wrap;
    }
    .trrsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .trrsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}



/* \u2500\u2500 v1.1.0 completion scorecard (append-only, namespaced .trade-cm-*, sustainability green/slate/amber) \u2500\u2500 */
.trade-cm { margin-top: 8px; }
.trade-cm-incomplete { text-align: center; color: #4a5b53; font-size: 1rem; padding: 18px; }
.trade-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.trade-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0f5132 0%, #1a7f5a 58%, #c98a1c 135%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(15, 81, 50, 0.28); }
.trade-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.trade-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.trade-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #ffe0a3; }
.trade-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #d5e2da; border-left: 5px solid #1a7f5a; border-radius: 14px; padding: 16px 20px; }
.trade-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b62; }
.trade-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #0f5132; line-height: 1.15; }
.trade-cm-section { margin-bottom: 16px; }
.trade-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b62; margin-bottom: 8px; }
.trade-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.trade-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.trade-cm-ok { background: rgba(26, 127, 90, 0.14); color: #1a7f5a; border-color: rgba(26, 127, 90, 0.42); }
.trade-cm-no { background: rgba(199, 84, 80, 0.12); color: #c75450; border-color: rgba(199, 84, 80, 0.42); }
.trade-cm-ico { font-weight: 800; }
.trade-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.trade-cm-kpi { background: #ffffff; border: 1px solid #d5e2da; border-top: 4px solid #c98a1c; border-radius: 12px; padding: 14px 12px; text-align: center; }
.trade-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #0f5132; line-height: 1; }
.trade-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #1f2d28; }
.trade-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #5a6b62; }
.trade-cm-insights { margin: 0; padding-left: 18px; color: #1f2d28; }
.trade-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .trade-cm-head { flex-direction: column; } .trade-cm-score { min-width: 0; } }

