(function() {
    'use strict';

    class TradeRulesAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Trade, Rules and Risk`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // NUMBERS REFERENCE CARD — Saraswati Textiles & Exports Ltd. (INR crore).
            this.FREE_CASH_FLOW = 85;    // ~INR 85 crore/year — the hard cash constraint
            this.REMEDIATION_NEED = 90;  // midpoint of INR 70–110 crore to bring all 14 units to standard
            this.GOODS_ON_HOLD = 96;     // INR 96 crore EU spring shipment frozen
            this.LARGEST_BUYER = 260;    // INR 260 crore/year, 22% of revenue
            this.EU_US_SHARE = 75;       // % of revenue (INR 885 crore)

            // Concept truths (the reserved-rights hybrid that manages both clocks).
            this.TRUE_RANK = `speed`;
            this.TRUE_POSTURE = `hybrid`;
            this.TRUE_GOV = `reserve`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    access: 100,             // Market access: EU+US revenue secured (higher better)
                    legal: 55,               // Legal exposure: own non-compliance + dispute-loss risk (lower better)
                    rep: 50,                 // Reputational risk: NGO / buyer ESG / investor (lower better)
                    jobs: 100,               // Workers protected: share of sub-contractor jobs kept & remediated
                    budgetUsed: 0,           // INR crore of compliance + remediation cost committed
                    underfunded: false,
                    harmRelocated: false,
                    confessed: false,
                    accessHistory: [100],
                    legalHistory: [55],
                    repHistory: [50],
                    jobsHistory: [100],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC ERRORS so a blind
                // click-through cannot auto-win: legal-first, deny own exposure,
                // dispute-clock, underfunded remediation, dumping, ignore NGO.
                state.decisions = {
                    rank: `legal`,
                    self: `own`,
                    quant: 40,
                    posture: `fight`,
                    gov: `align`,
                    clockChoice: `dispute`,
                    remediate: 25,
                    insource: 20,
                    grievance: 15,
                    exit: `dump`,
                    ngo: `ignore`,
                    buyer: `promise`,
                    board: `margin`,
                    ministry: `confess`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rk = document.getElementById(`rankInput`);
                const sf = document.getElementById(`selfInput`);
                const qt = document.getElementById(`quantInput`);
                if (rk) decisions.rank = rk.value;
                if (sf) decisions.self = sf.value;
                if (qt) decisions.quant = parseInt(qt.value, 10);
                if (!Number.isFinite(decisions.quant) || decisions.quant < 0 || decisions.quant > 100) {
                    warn(`warn_quant_range`); return false;
                }
            } else if (round === 2) {
                const ps = document.getElementById(`postureInput`);
                const gv = document.getElementById(`govInput`);
                const ck = document.getElementById(`clockChoice`);
                if (ps) decisions.posture = ps.value;
                if (gv) decisions.gov = gv.value;
                if (ck) decisions.clockChoice = ck.value;
            } else if (round === 3) {
                const rm = document.getElementById(`remediateInput`);
                const ins = document.getElementById(`insourceInput`);
                const gr = document.getElementById(`grievanceInput`);
                const ex = document.getElementById(`exitInput`);
                const ng = document.getElementById(`ngoInput`);
                if (rm) decisions.remediate = parseFloat(rm.value);
                if (ins) decisions.insource = parseFloat(ins.value);
                if (gr) decisions.grievance = parseFloat(gr.value);
                if (ex) decisions.exit = ex.value;
                if (ng) decisions.ngo = ng.value;
                const parts = [decisions.remediate, decisions.insource, decisions.grievance];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.remediate + decisions.insource + decisions.grievance);
                if (total > this.FREE_CASH_FLOW) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const by = document.getElementById(`buyerInput`);
                const bd = document.getElementById(`boardInput`);
                const mn = document.getElementById(`ministryInput`);
                const cv = document.getElementById(`convictionInput`);
                if (by) decisions.buyer = by.value;
                if (bd) decisions.board = bd.value;
                if (mn) decisions.ministry = mn.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let accessDelta = 0, legalDelta = 0, repDelta = 0, jobsDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ROUND 1 — Diagnose the exposure (Common Error 1: litigation tunnel vision).
                // The binding constraint is the commercial/reputational clock, not the dispute.
                switch (d.rank) {
                    case `speed`: legalDelta -= 4; repDelta -= 6; accessDelta += 2; coachKey = `coach_r1_speed`; break;
                    case `legal`: accessDelta -= 6; repDelta += 6; coachKey = `coach_r1_legal`; break;
                    case `rep`: legalDelta += 4; accessDelta -= 4; coachKey = `coach_r1_rep`; break;
                    case `equal`: repDelta += 3; coachKey = `coach_r1_equal`; break;
                }

                // Honest self-diagnosis: Saraswati's liability does not stop at the factory gate.
                switch (d.self) {
                    case `subs`: legalDelta -= 6; repDelta -= 4; coachKey = (d.rank === `speed`) ? `coach_r1_sharp` : coachKey; break;
                    case `own`: legalDelta += 5; repDelta += 4; break;
                    case `deny`: legalDelta += 9; repDelta += 8; coachKey = `coach_r1_deny`; break;
                }

                // Quantify revenue-at-risk: under-stating the existential 75% is a board failure.
                if (d.quant >= 60) { repDelta -= 3; legalDelta -= 2; }
                else if (d.quant <= 20) { repDelta += 5; coachKey = `coach_r1_understate`; }

                summaryKey = (d.rank === `speed` && d.self === `subs`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ROUND 2 — Choose the legal-compliance posture (Common Errors 1 & 2).
                switch (d.posture) {
                    case `hybrid`:
                        accessDelta += 10; legalDelta -= 6; repDelta -= 4; coachKey = `coach_r2_hybrid`; break;
                    case `comply`:
                        // Saves access but, if unreserved, the public confession undercuts the dispute.
                        accessDelta += 12; repDelta -= 6; legalDelta += 6; coachKey = `coach_r2_comply`; break;
                    case `fight`:
                        // Litigation tunnel vision: the dispute clock loses you the buyers.
                        accessDelta -= 16; legalDelta -= 2; repDelta += 8; coachKey = `coach_r2_fight`; break;
                }

                // Align with / reserve from / abandon the government's dispute.
                switch (d.gov) {
                    case `reserve`:
                        legalDelta -= 8; accessDelta += 4; if (d.posture === `hybrid`) coachKey = `coach_r2_reserved`; break;
                    case `align`:
                        // Aligning fully + holding trade = you ride the dispute clock and lose buyers.
                        if (d.posture === `fight`) { accessDelta -= 6; } else { legalDelta += 4; }
                        coachKey = (coachKey === `coach_default`) ? `coach_r2_align` : coachKey; break;
                    case `distance`:
                        // Unreserved confession (Common Error 2): settles the dispute for the industry.
                        legalDelta += 8; ds.confessed = true; coachKey = `coach_r2_confess`; break;
                }

                // Which clock governs the next 60 days (Common Error 1).
                if (d.clockChoice === `commercial`) { accessDelta += 6; repDelta -= 4; }
                else { accessDelta -= 10; repDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r2_disputeclock` : coachKey; }

                summaryKey = (d.posture === `hybrid` && d.gov === `reserve` && d.clockChoice === `commercial`) ? `sum_r2_good` :
                             (d.posture === `fight` ? `sum_r2_fight` : `sum_r2_weak`);
            } else if (round === 3) {
                // ROUND 3 — Human-rights due diligence under the deadline (Common Errors 3 & 4).
                const rm = d.remediate, ins = d.insource, gr = d.grievance;
                const funded = rm + ins;                 // capital that actually brings units to standard
                const totalSpend = rm + ins + gr;
                spend += totalSpend;

                // Funding coverage vs the INR 70–110 crore need (Common Error 3: underfunded promise).
                const coverage = Math.min(1, funded / this.REMEDIATION_NEED);
                accessDelta += Math.round(coverage * 16) - 4;
                repDelta -= Math.round(coverage * 14) - 3;
                legalDelta -= Math.round(coverage * 12) - 2;

                if (funded < 30) { ds.underfunded = true; coachKey = `coach_r3_underfunded`; }

                // Grievance / third-party audit / living-wage = the verifiable evidence (HRDD).
                if (gr >= 10) { repDelta -= 6; legalDelta -= 5; accessDelta += 4; }
                else { repDelta += 5; legalDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_noevidence` : coachKey; }

                // Exit strategy (Common Error 4: harm relocation vs responsible exit).
                switch (d.exit) {
                    case `responsible`: jobsDelta += 6; repDelta -= 5; legalDelta -= 3; break;
                    case `dump`:
                        // Cut all 14 overnight: 30% capacity & hundreds of women's jobs gone.
                        jobsDelta -= 45; accessDelta -= 10; repDelta += 12; ds.harmRelocated = true; coachKey = `coach_r3_dump`; break;
                    case `keep`:
                        // Quietly keep sourcing non-compliant units: the audit finds them.
                        legalDelta += 10; repDelta += 10; coachKey = `coach_r3_keep`; break;
                }

                // NGO engagement before the 45-day publication (Common Error 5: ignore the NGO).
                switch (d.ngo) {
                    case `engage`: repDelta -= 12; legalDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_engage` : coachKey; break;
                    case `legal`: repDelta += 10; coachKey = `coach_r3_ngolegal`; break;
                    case `ignore`: repDelta += 14; coachKey = `coach_r3_ngoignore`; break;
                }

                summaryKey = (coverage >= 0.7 && d.exit === `responsible` && d.ngo === `engage` && gr >= 10) ? `sum_r3_good` :
                             (ds.underfunded ? `sum_r3_underfunded` : (d.exit === `dump` ? `sum_r3_dump` : `sum_r3_weak`));
            } else if (round === 4) {
                // ROUND 4 — Decide and recover: the board & buyer defence (Common Error 5: single-KPI).
                switch (d.buyer) {
                    case `evidence`: accessDelta += 14; repDelta -= 8; legalDelta -= 4; coachKey = `coach_r4_evidence`; break;
                    case `promise`: accessDelta += 4; repDelta += 8; legalDelta += 3; coachKey = `coach_r4_promise`; break;
                    case `deny`: accessDelta -= 14; repDelta += 6; coachKey = `coach_r4_deny`; break;
                }

                // Board pitch: integrated multi-KPI vs single-objective optimisation.
                switch (d.board) {
                    case `integrated`: accessDelta += 6; legalDelta -= 5; repDelta -= 5; jobsDelta += 3; coachKey = `coach_r4_integrated`; break;
                    case `margin`: accessDelta -= 6; repDelta += 8; jobsDelta -= 6; coachKey = `coach_r4_margin`; break;
                    case `single`: legalDelta += 6; repDelta += 6; jobsDelta -= 4; coachKey = `coach_r4_single`; break;
                }

                // Trade-ministry question: reserved rights vs the unreserved confession.
                switch (d.ministry) {
                    case `reserved`: legalDelta -= 8; coachKey = (d.buyer === `evidence`) ? `coach_r4_held` : coachKey; break;
                    case `confess`: legalDelta += 10; ds.confessed = true; coachKey = `coach_r4_confess`; break;
                    case `abandon`: legalDelta += 6; repDelta += 4; coachKey = `coach_r4_abandon`; break;
                }

                if (d.conviction >= 60) { accessDelta += 3; repDelta -= 3; }
                else if (d.conviction <= 25) { repDelta += 4; }

                summaryKey = (d.buyer === `evidence` && d.board === `integrated` && d.ministry === `reserved`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: cumulative compliance + remediation cost vs free cash flow.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);

            // Apply deltas, clamped 0–100.
            ds.access = Math.max(0, Math.min(100, Math.round(ds.access + accessDelta)));
            ds.legal = Math.max(0, Math.min(100, Math.round(ds.legal + legalDelta)));
            ds.rep = Math.max(0, Math.min(100, Math.round(ds.rep + repDelta)));
            ds.jobs = Math.max(0, Math.min(100, Math.round(ds.jobs + jobsDelta)));

            ds.accessHistory.push(ds.access);
            ds.legalHistory.push(ds.legal);
            ds.repHistory.push(ds.rep);
            ds.jobsHistory.push(ds.jobs);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook actually reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                access: ds.access,
                accessDelta: Math.round(accessDelta),
                legal: ds.legal,
                legalDelta: Math.round(legalDelta),
                rep: ds.rep,
                repDelta: Math.round(repDelta),
                jobs: ds.jobs,
                jobsDelta: Math.round(jobsDelta),
                budgetUsed: ds.budgetUsed,
                underfunded: ds.underfunded,
                harmRelocated: ds.harmRelocated,
                confessed: ds.confessed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

