        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const access = Math.round(ds.access);
            const legal = Math.round(ds.legal);
            const rep = Math.round(ds.rep);
            const jobs = Math.round(ds.jobs);
            return Math.round(access * 0.32 + (100 - legal) * 0.24 + (100 - rep) * 0.26 + jobs * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const access = Math.round(ds.access);
            const legal = Math.round(ds.legal);
            const rep = Math.round(ds.rep);
            const jobs = Math.round(ds.jobs);

            // Composite extracted to _composite() so the persisted per-period score and this
            // completion summary are identical by construction (v1.1.0).
            const composite = this._composite(ds);

            const accessHeld = access >= 65;
            const legalManaged = legal <= 40;
            const reputationHeld = rep <= 40;
            const workersProtected = jobs >= 70;
            const exposed = rep >= 65 || (ds.underfunded && rep >= 50);
            const harmRelocated = ds.harmRelocated;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_unresolved`;
            if (accessHeld && legalManaged && reputationHeld && workersProtected && composite >= 75) tierKey = `grade_both`;
            else if (accessHeld && reputationHeld && workersProtected) tierKey = `grade_accessheld`;
            else if (harmRelocated) tierKey = `grade_harmreloc`;
            else if (exposed) tierKey = `grade_ngo`;
            else if (access <= 45) tierKey = `grade_buyerswalked`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (accessHeld && legalManaged && reputationHeld && workersProtected) insights.push(window.mySimulation.t(`insight_resolved`));
            else if (harmRelocated) insights.push(window.mySimulation.t(`insight_harm`));
            else if (exposed) insights.push(window.mySimulation.t(`insight_exposed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (access <= 50) insights.push(window.mySimulation.t(`insight_access_lost`));
            else if (access >= 80) insights.push(window.mySimulation.t(`insight_access_held`));
            if (ds.confessed) insights.push(window.mySimulation.t(`insight_confessed`));
            if (ds.underfunded) insights.push(window.mySimulation.t(`insight_underfunded`));
            if (jobs < 60) insights.push(window.mySimulation.t(`insight_jobs`));
            if (legal <= 30 && rep <= 30) insights.push(window.mySimulation.t(`insight_defensible`));

            return {
                access: access,
                legal: legal,
                rep: rep,
                jobs: jobs,
                accessHeld: accessHeld,
                legalManaged: legalManaged,
                reputationHeld: reputationHeld,
                workersProtected: workersProtected,
                harmRelocated: harmRelocated,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
