            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="trade-cm">` +
  `<div class="trade-cm-head">` +
    `<div class="trade-cm-score"><div class="trade-cm-score-num">` + Math.round(s.composite) +
