    `</div></div>` +
  (insights ? `<div class="trade-cm-section"><div class="trade-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="trade-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
